<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {clone,familyLabels,getStudio,overnightLabels,saveStudio,type StudioPayload,type StudioPlace} from './content-studio-api';import {getVisitorState,type VPayload} from './visitor-content-api';
const route=useRoute(),payload=ref<StudioPayload|null>(null),visitor=ref<VPayload|null>(null),place=ref<StudioPlace|null>(null),message=ref(''),busy=ref(false),fieldMode=ref(false),tab=ref<'edit'|'preview'>('edit');
async function load(){[payload.value,visitor.value]=await Promise.all([getStudio(),getVisitorState()]);place.value=clone(payload.value.document.places[String(route.params.code)]);}onMounted(load);
const themes=computed(()=>payload.value?.document.themes.filter(t=>!t.archivedAt)||[]);const routes=computed(()=>payload.value?.document.routes.filter(r=>r.memberships.some(m=>m.placeId===place.value?.id))||[]);
function today(){if(place.value)place.value.trust.lastCheckedAt=new Date().toISOString().slice(0,10);}
async function save(summary='修改地点资料'){if(!payload.value||!place.value)return;busy.value=true;try{const doc=clone(payload.value.document);doc.places[place.value.id]=clone(place.value);const result=await saveStudio(payload.value,doc,'place',place.value.id,`${summary}：${place.value.name.zh}`);message.value=`草稿已保存（版本 ${result.draftRevision}），公开网站尚未改变。`;await load();}catch(e){message.value=(e as Error).message;}finally{busy.value=false;}}
function addLink(kind:'videos'|'storyLinks'|'researchLinks'){if(!place.value)return;place.value[kind].push({id:crypto.randomUUID(),title:{zh:'',en:''},url:'',...(kind==='videos'?{platform:'douyin' as const}: {})});}
function addPhoto(fileName:string){if(!place.value||place.value.photos.some(photo=>photo.fileName===fileName))return;place.value.photos.push({id:crypto.randomUUID(),fileName,alt:{zh:`${place.value.name.zh}现场照片`,en:''},role:place.value.photos.length?'gallery':'cover',order:place.value.photos.length*10});}
</script>
<template><div v-if="payload&&place" class="workspace-page studio-page place-studio"><div class="workspace-title"><div><RouterLink to="/studio/places">← 返回地点</RouterLink><p class="kicker">{{place.id}}</p><h1>{{place.name.zh}}</h1><p>{{place.trust.checkedInPerson?'实地核验':'尚未标记实地核验'}} · 最近核验：{{place.trust.lastCheckedAt||'未填写'}}</p></div><div class="workspace-actions"><button class="quiet" @click="fieldMode=!fieldMode">{{fieldMode?'退出现场更新':'现场更新'}}</button><a class="button quiet" :href="`/zh/place/${place.id}/`" target="_blank">预览公开页</a><button class="primary-action" :disabled="busy" @click="save()">保存草稿</button></div></div><p v-if="message" class="inline-message">{{message}}</p>
<div class="edit-preview-tabs"><button :class="tab==='edit'?'active':''" @click="tab='edit'">编辑</button><button :class="tab==='preview'?'active':''" @click="tab='preview'">预览</button></div>
<section v-if="fieldMode" class="field-update"><h2>现场更新</h2><div class="field-actions"><button @click="place.trust.firsthand=true">设为已实地到访</button><button @click="today">最近核验 = 今天</button><RouterLink class="button" :to="`/places/${place.id}?relocate=1`">使用当前位置 / 安全改位置</RouterLink><button @click="place.publicStatus='开放'">开放</button><button @click="place.publicStatus='关闭'">关闭</button><button @click="place.publicStatus='在建'">在建</button><button @click="place.trust.recheckBeforeGoing=true">需重新确认</button></div><textarea v-model="place.firsthandNotes.zh" rows="3" placeholder="添加一条实地记录"></textarea><button class="primary-action" @click="save('现场快速更新')">保存现场草稿</button></section>
<div v-if="tab==='preview'" class="place-live-preview"><div class="studio-place-cover large"><img v-if="place.photos[0]" :src="`/api/admin/visitor-content/media/${place.photos[0].fileName}`"><span v-else>{{place.category.includes('茶')?'茶':place.category.includes('展馆')?'馆':'地'}}</span></div><article><small>{{place.region.zh}}</small><h2>{{place.name.zh}}</h2><p>{{place.summary.zh}}</p><div class="visual-card-tags"><span v-for="id in place.themeIds">{{themes.find(t=>t.id===id)?.name.zh}}</span><span v-if="place.facilities.toilet">卫生间</span><span v-if="place.facilities.food">餐饮</span><span v-if="place.facilities.shop">商店</span><span v-if="place.facilities.lodging">住宿</span></div></article></div>
<div v-else class="place-editor-sections"><details open><summary>基本信息</summary><div class="form-grid"><label>中文名称<input v-model="place.name.zh"></label><label>英文名称<input v-model="place.name.en" placeholder="可后补，不自动机器翻译"></label><label>中文简称<input v-model="place.shortName.zh"></label><label>英文简称<input v-model="place.shortName.en"></label><label>拼音<input v-model="place.pinyin"></label><label>英文名称状态<select v-model="place.englishNameStatus"><option value="pending">待人工核验</option><option value="pinyin">拼音</option><option value="translated">人工翻译</option><option value="established">通行英文名</option><option value="official">官方英文名</option></select></label><label>所属区域<input v-model="place.region.zh"></label><label>地址<input v-model="place.address.zh"></label><label>地图标签优先级<select v-model.number="place.labelPriority"><option :value="100">100 · 路线骨架</option><option :value="80">80 · 重要地点</option><option :value="60">60 · 一般停留</option><option :value="40">40 · 补给/支线</option><option :value="20">20 · 次级服务</option></select></label><label class="inline-check"><input v-model="place.published" type="checkbox">公开显示</label><label class="inline-check"><input v-model="place.recommended" type="checkbox">推荐显示</label></div><div class="map-label-preview"><span>远景只显示点位</span><b>{{place.shortName.zh||place.name.zh}}</b><strong>{{place.name.zh}}</strong></div><RouterLink class="button quiet" :to="`/places/${place.id}?relocate=1`">安全编辑地图位置</RouterLink></details>
<details open><summary>介绍</summary><div class="form-grid"><label class="wide">简介<textarea v-model="place.summary.zh"></textarea></label><label class="wide">为什么值得停<textarea v-model="place.whyStop.zh"></textarea></label><label class="wide">Jeff 实地记录<textarea v-model="place.firsthandNotes.zh"></textarea></label><label class="wide">开放与实用信息<textarea :value="place.practicalInfo.zh.join('\n')" @input="place.practicalInfo.zh=($event.target as HTMLTextAreaElement).value.split('\n').filter(Boolean)"></textarea></label><label class="wide">安全提示<textarea v-model="place.safetyNotes.zh"></textarea></label><label class="wide">到达方式<textarea v-model="place.accessNotes.zh"></textarea></label><label class="wide">季节提示<textarea v-model="place.seasonNotes.zh"></textarea></label></div></details>
<details><summary>出行信息</summary><div class="facility-grid"><label><input v-model="place.facilities.parking" type="checkbox">停车</label><label><input v-model="place.facilities.toilet" type="checkbox">卫生间</label><label><input v-model="place.facilities.food" type="checkbox">餐饮</label><label><input v-model="place.facilities.shop" type="checkbox">商店</label><label><input v-model="place.facilities.lodging" type="checkbox">住宿</label></div><div class="form-grid"><label>停车说明<input v-model="place.parking.zh"></label><label>卫生间位置<input v-model="place.toiletNote.zh"></label><label>餐饮说明<input v-model="place.foodNote.zh"></label><label>商店说明<input v-model="place.shopNote.zh"></label><label>住宿说明<input v-model="place.lodgingNote.zh"></label></div></details>
<details><summary>亲子</summary><div class="choice-grid"><label v-for="(label,key) in familyLabels"><input v-model="place.familySuitability" type="radio" :value="key">{{label}}</label></div><textarea v-model="place.familyNotes.zh" placeholder="亲子说明"></textarea></details>
<details><summary>床车过夜</summary><div class="choice-grid overnight"><label v-for="(label,key) in overnightLabels"><input v-model="place.overnightStatus" type="radio" :value="key">{{label}}</label></div><textarea v-model="place.overnightNotes.zh" placeholder="补充说明"></textarea><div class="form-grid"><label>最后确认日期<input v-model="place.overnightLastCheckedAt" type="date"></label><label>来源<input v-model="place.overnightSource"></label></div></details>
<details><summary>实地核验</summary><div class="trust-grid"><label><input v-model="place.trust.firsthand" type="checkbox">我亲自到过</label><label><input v-model="place.trust.checkedInPerson" type="checkbox">我亲自核验过信息</label><label><input v-model="place.trust.officialSource" type="checkbox">有官方资料</label><label><input v-model="place.trust.recheckBeforeGoing" type="checkbox">出发前需要重新确认</label></div><button @click="today">最近核验设为今天</button><input v-model="place.trust.lastCheckedAt" type="date"></details>
<details><summary>路线与分类</summary><p>所属路线：{{routes.map(r=>r.name.zh).join('、')||'未加入路线'}}</p><div class="theme-checks"><label v-for="theme in themes"><input v-model="place.themeIds" type="checkbox" :value="theme.id">{{theme.name.zh}}</label></div></details>
<details><summary>照片</summary><p v-if="!place.photos.length">尚未设置封面。可以从媒体库选择，或先上传新照片。</p><div v-for="(photo,index) in place.photos" class="media-row"><img :src="`/api/admin/visitor-content/media/${photo.fileName}`"><input v-model="photo.alt.zh" placeholder="中文图片说明"><select v-model="photo.role"><option value="cover">封面</option><option value="gallery">图集</option></select><button class="remove-button" @click="place.photos.splice(index,1)">移除关联</button></div><div class="media-library-grid compact"><button v-for="(image,slot) in visitor?.state.media.items" :key="slot" type="button" @click="addPhoto(image.fileName)"><img :src="`/api/admin/visitor-content/media/${image.fileName}`"><span>{{image.originalName}}</span></button></div><RouterLink class="button quiet" to="/studio/media">上传新照片</RouterLink></details>
<details><summary>视频</summary><div v-for="video in place.videos" class="link-editor"><select v-model="video.platform"><option>douyin</option><option>youtube</option><option>instagram</option><option>tiktok</option></select><input v-model="video.title.zh" placeholder="标题"><input v-model="video.url" placeholder="https://"></div><button @click="addLink('videos')">＋ 关联视频</button></details>
<details><summary>故事与研究</summary><h3>故事</h3><div v-for="item in place.storyLinks" class="link-editor"><input v-model="item.title.zh" placeholder="标题"><input v-model="item.url" placeholder="https://"></div><button @click="addLink('storyLinks')">＋ 故事</button><h3>研究资料</h3><div v-for="item in place.researchLinks" class="link-editor"><input v-model="item.title.zh" placeholder="标题"><input v-model="item.url" placeholder="https://"></div><button @click="addLink('researchLinks')">＋ 研究资料</button></details>
<details><summary>英文</summary><div class="form-grid"><label class="wide">English summary<textarea v-model="place.summary.en"></textarea></label><label class="wide">Why stop<textarea v-model="place.whyStop.en"></textarea></label><label class="wide">Field notes<textarea v-model="place.firsthandNotes.en"></textarea></label><label class="wide">Safety<textarea v-model="place.safetyNotes.en"></textarea></label></div></details></div><div class="editor-action-bar"><span>保存不会立即影响公开网站</span><button class="primary-action" :disabled="busy" @click="save()">保存地点草稿</button></div></div></template>
